import heapq

def k_largest(nums, k):
    heap = nums[:k]
    heapq.heapify(heap)  # min-heap of size k
    for x in nums[k:]:
        if x > heap[0]:
            heapq.heapreplace(heap, x)
    return sorted(heap, reverse=True)

print(k_largest([3, 2, 1, 5, 6, 4], 3))
